/* ══════════════════════════════════════════════════
   THE ŠAKAL MARK
   The jackal, as it appears on the invoice beside the
   name. Loaded only when an invoice PDF is made.

   ratio is width ÷ height: the PDF picks the height
   and works the width out from this, so the mark can
   never come out stretched.
   ══════════════════════════════════════════════════ */

window.SAKAL_LOGO = {
  type: 'PNG',
  ratio: 0.5846,
  data: 'data:image/png;base64,'
};
